/// The item name's own row (the `minecraft:`-prefixed id the table
/// speaks). The client resolves the held item's name through the
/// registry's own item-name lane first.
pub fn food_def(id: &str) -> Option<&'static FoodDef> {
    FOODS.iter().find(|f| f.id == id)
}

/// The FOOD/CONSUMABLE row by the bare item name (the registry's
/// item ids speak without the `minecraft:` prefix).
pub fn food_def_by_name(name: &str) -> Option<&'static FoodDef> {
    food_def(&format!("minecraft:{name}"))
}

